INSERT INTO `company_info` VALUES (1,'MISSION','An efficient and well-managed government corporation developing and managing modern, resilient, and multi-purpose Irrigation Systems to improve agricultural productivity and increase farmer\'s incom',1,'2025-09-29 06:25:31'),(2,'VISION','By 2023, NIA is an advanced and innovative irrigation agency enabling highly competitive and sustainable Philippine farming communities',1,'2025-09-29 06:23:49'),(3,'CORE VALUES','INTEGREGITY\r\nINNOVATION\r\nCOMMITMET\r\nEXCELLENCE',1,'2025-10-11 02:34:21'),(4,'INTEGRATED MANAGEMENT SYSTEM POLICY','We commit to provide efficient, effective, and sustainable irrigation services aimed towards the highest satisfaction of the Filipino farmers.\r\n\r\nWe strive for the attainment of our strategic themes of Technical and Operational Excellence, and Good Governance through partnership with the farmers and other relevant interested parties.\r\n\r\nWe commit to establish programs that prevent work-related injury and ill health, and encourage participation and consultation of workers within the Agency.\r\n\r\nWe abide with applicable legal and international requirements and we remain dedicated to the core values of Integrity, Innovation, Commitment and Excellence, to continually improve the NIA’s Integrated Management System.',1,'2025-10-11 02:34:19');
