--
-- Table structure for table `document_records`
--

DROP TABLE IF EXISTS `document_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `document_records` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `document_number` varchar(100) NOT NULL,
  `document_name` text NOT NULL,
  `document_type_id` int(11) NOT NULL,
  `kind` enum('incoming','outgoing','external') NOT NULL,
  `forwarded_by_emp_id` int(11) DEFAULT NULL,
  `forwarded_to_emp_id` int(11) DEFAULT NULL,
  `forwarded_by_name` varchar(200) DEFAULT NULL,
  `from_section_id` int(11) DEFAULT NULL,
  `from_unit_id` int(11) DEFAULT NULL,
  `forwarded_to` varchar(255) NOT NULL,
  `forwarded_to_section_id` int(11) DEFAULT NULL,
  `forwarded_to_unit_id` int(11) DEFAULT NULL,
  `forwarded_to_office_id` int(11) DEFAULT NULL,
  `date_forwarded` timestamp NOT NULL DEFAULT current_timestamp(),
  `date_received` timestamp NOT NULL DEFAULT current_timestamp(),
  `received_by_emp_id` int(11) DEFAULT NULL COMMENT 'Employee who marked this document as received',
  `remarks` text DEFAULT NULL,
  `status` enum('pending','received','returned','completed','archived') DEFAULT 'pending',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_by_emp_id` int(11) DEFAULT NULL COMMENT 'emp_id of the user who originally added this document',
  PRIMARY KEY (`id`),
  KEY `fk_doc_type` (`document_type_id`),
  KEY `fk_from_section` (`from_section_id`),
  KEY `fk_to_section` (`forwarded_to_section_id`),
  KEY `fk_forwarded_by` (`forwarded_by_emp_id`),
  KEY `fk_forwarded_to_emp` (`forwarded_to_emp_id`),
  KEY `fk_doc_received_by` (`received_by_emp_id`),
  CONSTRAINT `fk_doc_received_by` FOREIGN KEY (`received_by_emp_id`) REFERENCES `employee` (`emp_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_doc_type` FOREIGN KEY (`document_type_id`) REFERENCES `document_types` (`id`),
  CONSTRAINT `fk_forwarded_by_emp` FOREIGN KEY (`forwarded_by_emp_id`) REFERENCES `employee` (`emp_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_forwarded_to_emp` FOREIGN KEY (`forwarded_to_emp_id`) REFERENCES `employee` (`emp_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_from_section` FOREIGN KEY (`from_section_id`) REFERENCES `section` (`section_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_to_section` FOREIGN KEY (`forwarded_to_section_id`) REFERENCES `section` (`section_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=486 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

