--
-- Table structure for table `employee`
--

DROP TABLE IF EXISTS `employee`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `employee` (
  `emp_id` int(11) NOT NULL AUTO_INCREMENT,
  `picture` varchar(255) NOT NULL,
  `id_number` varchar(50) DEFAULT NULL,
  `first_name` varchar(50) NOT NULL,
  `middle_name` varchar(50) NOT NULL,
  `last_name` varchar(50) NOT NULL,
  `ext_name` varchar(10) DEFAULT NULL,
  `gender` enum('Male','Female','Other') NOT NULL,
  `address` text NOT NULL,
  `bday` date NOT NULL,
  `email` varchar(100) NOT NULL,
  `phone_number` varchar(20) NOT NULL,
  `employment_status_id` int(11) DEFAULT NULL,
  `appointment_status_id` int(11) DEFAULT NULL,
  `section_id` int(11) DEFAULT NULL,
  `office_id` int(11) DEFAULT NULL,
  `position_id` int(11) DEFAULT NULL,
  `unit_section_id` int(11) DEFAULT NULL,
  `is_manager` tinyint(1) DEFAULT 0,
  `reset_token` varchar(64) DEFAULT NULL,
  `reset_token_expiry` datetime DEFAULT NULL,
  `is_manager_office_staff` tinyint(1) DEFAULT 0,
  PRIMARY KEY (`emp_id`),
  KEY `employment_status_id` (`employment_status_id`),
  KEY `appointment_status_id` (`appointment_status_id`),
  KEY `section_id` (`section_id`),
  KEY `office_id` (`office_id`),
  KEY `position_id` (`position_id`),
  KEY `employee_ibfk_6` (`unit_section_id`),
  CONSTRAINT `employee_ibfk_1` FOREIGN KEY (`employment_status_id`) REFERENCES `employment_status` (`status_id`),
  CONSTRAINT `employee_ibfk_2` FOREIGN KEY (`appointment_status_id`) REFERENCES `appointment_status` (`appointment_id`),
  CONSTRAINT `employee_ibfk_3` FOREIGN KEY (`section_id`) REFERENCES `section` (`section_id`),
  CONSTRAINT `employee_ibfk_4` FOREIGN KEY (`office_id`) REFERENCES `office` (`office_id`),
  CONSTRAINT `employee_ibfk_5` FOREIGN KEY (`position_id`) REFERENCES `position` (`position_id`),
  CONSTRAINT `employee_ibfk_6` FOREIGN KEY (`unit_section_id`) REFERENCES `unit_section` (`unit_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=306 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

